177:     const g2=a.createGain();g2.gain.setValueAtTime(0.5,t);g2.gain.exponentialRampToValueAtTime(0.001,t+0.16);q.connect(g2);g2.connect(pn||a.destination);
178:     g.gain.setValueAtTime(o.v||0.5,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
