183:     const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=320;q.connect(f);chain(f);
184:     g.gain.setValueAtTime(0,(o.v||1)*0.06);g.gain.linearRampToValueAtTime((o.v||1)*0.07,t+0.18);g.gain.linearRampToValueAtTime(0,t+0.85);q.start(t);q.stop(t+0.9);}
185:   else if(kind==='scream'){const q=a.createOscillator();q.type='sawtooth';q.frequency.setValueAtTime(300,t);q.frequency.linearRampToValueAtTime(900,t+0.3);q.frequency.linearRampToValueAtTime(500,t+1.1);
