147: <script>
148: "use strict";
149: /* ================= CALL OF ZOMBIES: ROUND WAR =================
150:    Self-contained raycasting FPS engine. Xbox Gamepad API with
151:    CoD Zombies presets, rumble, hold-X buy. Touch + KB/Mouse.
152:    WebAudio synth SFX/music. LocalStorage profile. 4 maps, 7
153:    zombie types, 22 weapons, perks, WAR FORGE, bosses, eggs. */
154: const $=(i)=>document.getElementById(i);
155: const clamp=(v,a,b)=>v<a?a:v>b?b:v, rnd=(a,b)=>a+Math.random()*(b-a), ri=(a,b)=>Math.floor(rnd(a,b+1));
156: const TAU=Math.PI*2, angN=a=>{while(a>Math.PI)a-=TAU;while(a<-Math.PI)a+=TAU;return a;};
157: const SAVE=(k,v)=>{try{localStorage.setItem('czrw_'+k,JSON.stringify(v));}catch(e){}};
158: const LOAD=(k,d)=>{try{const v=localStorage.getItem('czrw_'+k);return v==null?d:JSON.parse(v);}catch(e){return d;}};
159: const settings={preset:LOAD('preset','default'),sens:LOAD('sens',1),invert:LOAD('invert',false),quality:LOAD('quality','high'),fov:LOAD('fov',80),mapId:LOAD('mapId',0)};
160: 
161: /* ---------------- AUDIO ---------------- */
162: let AC=null,muted=false,musGain=null,musLvl=0;
163: function ac(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
164: let _noise=null;
165: function noiseBuf(){const a=ac();if(!a)return null;if(!_noise){_noise=a.createBuffer(1,a.sampleRate*0.6,a.sampleRate);const d=_noise.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;}return _noise;}
166: function panNode(pan){const a=ac();if(!a)return null;if(a.createStereoPanner){const p=a.createStereoPanner();p.pan.value=clamp(pan,-1,1);return p;}return a.createGain();}
167: function sfx(kind,o){o=o||{};if(muted)return;const a=ac();if(!a)return;const t=a.currentTime,g=a.createGain();
168:   let out=g; g.connect(a.destination); let pn=null;
169:   if(o.pan!=null){pn=panNode(o.pan);g.disconnect();g.connect(pn);pn.connect(a.destination);}
170:   const chain=(n)=>{n.connect(g);};
171:   if(kind==='shot'||kind==='shotgun'||kind==='sniper'){
172:     const dur=kind==='shotgun'?0.35:(kind==='sniper'?0.4:0.16);
173:     const s=a.createBufferSource();s.buffer=noiseBuf();const f=a.createBiquadFilter();f.type='lowpass';
174:     f.frequency.setValueAtTime(kind==='sniper'?800:2600,t);f.frequency.exponentialRampToValueAtTime(150,t+dur);
175:     s.connect(f);chain(f);
176:     const q=a.createOscillator();q.type='square';q.frequency.setValueAtTime(kind==='shotgun'?85:kind==='sniper'?70:140,t);q.frequency.exponentialRampToValueAtTime(35,t+0.13);
177:     const g2=a.createGain();g2.gain.setValueAtTime(0.5,t);g2.gain.exponentialRampToValueAtTime(0.001,t+0.16);q.connect(g2);g2.connect(pn||a.destination);
178:     g.gain.setValueAtTime(o.v||0.5,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
179:     s.start(t);s.stop(t+dur);q.start(t);q.stop(t+0.18);
180:   }else if(kind==='clickl'){const q=a.createOscillator();q.type='square';q.frequency.value=900;chain(q);g.gain.setValueAtTime(0.04,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.04);q.start(t);q.stop(t+0.05);}
181:     else if(kind==='clikh'){const q=a.createOscillator();q.type='square';q.frequency.value=1500;chain(q);g.gain.setValueAtTime(0.03,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.05);q.start(t);q.stop(t+0.06);}
182:   else if(kind==='groan'){const q=a.createOscillator();q.type='sawtooth';q.frequency.setValueAtTime(rnd(52,95),t);q.frequency.linearRampToValueAtTime(rnd(38,60),t+0.8);
183:     const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=320;q.connect(f);chain(f);
184:     g.gain.setValueAtTime(0,(o.v||1)*0.06);g.gain.linearRampToValueAtTime((o.v||1)*0.07,t+0.18);g.gain.linearRampToValueAtTime(0,t+0.85);q.start(t);q.stop(t+0.9);}
185:   else if(kind==='scream'){const q=a.createOscillator();q.type='sawtooth';q.frequency.setValueAtTime(300,t);q.frequency.linearRampToValueAtTime(900,t+0.3);q.frequency.linearRampToValueAtTime(500,t+1.1);
186:     const f=a.createBiquadFilter();f.type='bandpass';f.frequency.value=700;q.connect(f);chain(f);
187:     g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(0.22,t+0.2);g.gain.linearRampToValueAtTime(0,t+1.3);q.start(t);q.stop(t+1.35);}
188:   else if(kind==='boom'){const s=a.createBufferSource();s.buffer=noiseBuf();const f=a.createBiquadFilter();f.type='lowpass';
189:     f.frequency.setValueAtTime(700,t);f.frequency.exponentialRampToValueAtTime(60,t+0.9);s.connect(f);chain(f);
190:     const q=a.createOscillator();q.type='sine';q.frequency.setValueAtTime(70,t);q.frequency.exponentialRampToValueAtTime(28,t+0.9);
191:     const g2=a.createGain();g2.gain.setValueAtTime(0.7,t);g2.gain.exponentialRampToValueAtTime(0.001,t+1);q.connect(g2);g2.connect(pn||a.destination);
192:     g.gain.setValueAtTime(0.9,t);g.gain.exponentialRampToValueAtTime(0.001,t+1.0);s.start(t);s.stop(t+1);q.start(t);q.stop(t+1);}
193:   else if(kind==='hurt'){const s=a.createBufferSource();s.buffer=noiseBuf();const f=a.createBiquadFilter();f.type='bandpass';f.frequency.value=200;s.connect(f);chain(f);
194:     g.gain.setValueAtTime(0.45,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.35);s.start(t);s.stop(t+0.35);}
195:   else if(kind==='buy'){const q=a.createOscillator();q.type='triangle';q.frequency.setValueAtTime(660,t);q.frequency.setValueAtTime(1046,t+0.07);chain(q);
196:     g.gain.setValueAtTime(0.18,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.3);q.start(t);q.stop(t+0.31);}
197:   else if(kind==='deny'){const q=a.createOscillator();q.type='square';q.frequency.setValueAtTime(140,t);chain(q);g.gain.setValueAtTime(0.13,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.22);q.start(t);q.stop(t+0.23);}
