import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.goto('http://127.0.0.1:8765/index.html', { waitUntil: 'load' });
await page.evaluate(() => {
 gameCanvas.requestPointerLock=()=>{}; startGame(0);
 player.x=4.5; player.y=2.5; player.a=-Math.PI/2;
 const win=game.map.winW[0]; const z=spawnZombie('walker',win);
 z.x=4.5; z.y=-0.4; z.delay=999;
 window._oldS=drawS; window._oldZS=drawZombieS; window._oldDE=drawEntity;
 window._calls=[];
 drawS=function(img,s,cfg){window._calls.push(['S',s.tfX,s.tfY,cfg.throughWalls]);return window._oldS(img,s,cfg);};
 drawZombieS=function(z,s,t){window._calls.push(['ZS',z.st,s.tfY]);return window._oldZS(z,s,t);};
 drawEntity=function(s){if(s.kind==='zombie')window._calls.push(['DE',s.kind,s.tfY]);return window._oldDE(s);};
 window._direct=()=>{const z=zombies.find(z=>z.y===-.4);drawEntity({kind:'zombie',o:z,tfX:0,tfY:2});};
});
await page.waitForTimeout(300);
console.log(await page.evaluate(()=>({calls:_calls.slice(0,20),fn:{drawS:String(drawS).slice(0,80),drawZombieS:String(drawZombieS).slice(0,80),drawEntity:String(drawEntity).slice(0,80)},state:game.state,zbuf:zbuf[RW>>1],player:{x:player.x,y:player.y,a:player.a}})));
await page.evaluate(()=>_direct());
console.log('manual',await page.evaluate(()=>_calls.slice(-10)));
await page.screenshot({path:'/tmp/opencode/zombies-diag.jpg',type:'jpeg',quality:75});
await browser.close();

